  app2.get("/api/v1/dashboard/resources", async (req) => {
    const db = getDb();
    const projectId = getProjectId(req);
    const activeTasks = db.select().from(tasks).where(and(eq(tasks.status, "active"), eq(tasks.projectId, projectId))).all();
    const byOwner = {};
    for (const t of activeTasks) {
      const owner = t.owner || "unassigned";
      if (!byOwner[owner])
        byOwner[owner] = { tasks: 0, p0: 0, p1: 0, avgProgress: 0 };
      byOwner[owner].tasks++;
      byOwner[owner].avgProgress += t.progress;
      if (t.priority === "P0")
        byOwner[owner].p0++;
      if (t.priority === "P1")
        byOwner[owner].p1++;
    }
    for (const k of Object.keys(byOwner)) {
      byOwner[k].avgProgress = Math.round(byOwner[k].avgProgress / byOwner[k].tasks);
    }
    return { byOwner };
  });
